fn expectUniqueOutput(seen: *std.StringHashMapUnmanaged(void), output: []const u8) !void {
    try std.testing.expect(!seen.contains(output));
    try seen.put(std.testing.allocator, output, {});
}

test "generator declarations map typed inputs to unique Java outputs" {
    var outputs: std.StringHashMapUnmanaged(void) = .empty;
    defer outputs.deinit(std.testing.allocator);

    for (cronet.enum_outputs) |output| try expectUniqueOutput(&outputs, output);
    for (cronet.proto_outputs) |output| try expectUniqueOutput(&outputs, output);
    for (cronet.jni_outputs) |output| try expectUniqueOutput(&outputs, output);
    for (cronet.jni_final_outputs) |output| try expectUniqueOutput(&outputs, output);
    try expectUniqueOutput(&outputs, cronet.impl_version_output);
    try expectUniqueOutput(&outputs, cronet.switches_output);
    try expectUniqueOutput(&outputs, cronet.preload.output);
    try expectUniqueOutput(&outputs, cronet.api_version_output);
    inline for (cronet.templates) |entry| try expectUniqueOutput(&outputs, entry.output);
    for (hidl) |entry| {
        try std.testing.expect(std.mem.indexOfScalar(u8, entry.fqname, '@') != null);
        try std.testing.expect(entry.outputs.len != 0);
        for (entry.outputs) |output| {
            try std.testing.expect(std.mem.endsWith(u8, output, ".java"));
            try expectUniqueOutput(&outputs, output);
        }
    }
    for (aidl) |input| try std.testing.expect(std.mem.endsWith(u8, input.path, ".aidl"));
    for (logtags) |entry| {
        try std.testing.expect(std.mem.endsWith(u8, entry.input.path, ".logtags"));
        try std.testing.expect(std.mem.endsWith(u8, entry.output, ".java"));
        try expectUniqueOutput(&outputs, entry.output);
    }
    for (aconfig) |entry| {
        try std.testing.expect(entry.package.len != 0);
        try std.testing.expect(entry.container.len != 0);
        try std.testing.expect(entry.declarations.len != 0);
        for (entry.declarations) |path| try std.testing.expect(std.mem.endsWith(u8, path, ".aconfig"));
        for (entry.values) |path| try std.testing.expect(std.mem.endsWith(u8, path, ".textproto"));
    }
    for (sysprop) |entry| try std.testing.expect(std.mem.endsWith(u8, entry.input.path, ".sysprop"));
    for (nano) |entry| {
        try std.testing.expect(std.mem.endsWith(u8, entry.input.path, ".proto"));
        try std.testing.expect(std.mem.endsWith(u8, entry.output, ".java"));
        try expectUniqueOutput(&outputs, entry.output);
    }
    try expectUniqueOutput(&outputs, aconfig_device_paths.output);
    for (proto_inputs) |input| try std.testing.expect(std.mem.endsWith(u8, input.path, ".proto"));
    for (proto_outputs) |output| {
        try std.testing.expect(std.mem.endsWith(u8, output, ".java"));
        try expectUniqueOutput(&outputs, output);
    }
    try std.testing.expect(std.mem.startsWith(u8, perfetto_proto_include_filter, "include_filter:"));
    for (perfetto_proto_inputs) |input| try std.testing.expect(std.mem.endsWith(u8, input.path, ".proto"));
    for (perfetto_proto_outputs) |output| {
        try std.testing.expect(std.mem.startsWith(u8, output, "android/internal/perfetto/protos/"));
        try std.testing.expect(std.mem.endsWith(u8, output, ".java"));
        try expectUniqueOutput(&outputs, output);
    }
    for (stats_protos) |path| try std.testing.expect(std.mem.endsWith(u8, path, ".proto"));
}

